{
  "name": "UXBus TCP/Modbus 通信协议组件",
  "name_en": "UXBus TCP/Modbus Protocol Component",
  "manufacturer": "",
  "description": "这是一个非实体的软件通信组件，用于通过 TCP 封装、发送和解析 UXBus/Modbus 请求与响应报文。它提供线圈、离散输入、保持寄存器和输入寄存器的读写操作，适合在实验自动化系统中把上层控制程序与支持该协议的网络设备连接起来。",
  "description_en": "This is a non-physical software communication component that packages, sends, and parses UXBus/Modbus request and response frames over TCP. It provides read/write access to coils, discrete inputs, holding registers, and input registers, and is used in lab automation to connect higher-level control software to networked devices that speak this protocol.",
  "tag_hints": [
    "Modbus TCP",
    "protocol communication",
    "register read/write",
    "coil control",
    "TCP device interface",
    "industrial automation",
    "network command transport"
  ],
  "actions": [
    {
      "action_name": "auto-has_err_warn",
      "description": "获取/设置错误与告警标志",
      "description_en": "get/set error and warning flag"
    },
    {
      "action_name": "auto-set_protocol_identifier",
      "description": "设置协议标识符",
      "description_en": "set protocol identifier"
    },
    {
      "action_name": "auto-check_protocol_header",
      "description": "检查接收数据的协议头是否有效",
      "description_en": "check whether the received protocol header is valid"
    },
    {
      "action_name": "auto-check_private_protocol",
      "description": "检查是否为私有协议格式",
      "description_en": "check whether the data matches the private protocol format"
    },
    {
      "action_name": "auto-send_modbus_request",
      "description": "发送 Modbus TCP 请求报文",
      "description_en": "send a Modbus TCP request frame"
    },
    {
      "action_name": "auto-recv_modbus_response",
      "description": "接收并解析 Modbus TCP 响应报文",
      "description_en": "receive and parse a Modbus TCP response frame"
    },
    {
      "action_name": "auto-read_coil_bits",
      "description": "读取线圈位",
      "description_en": "read coil bits"
    },
    {
      "action_name": "auto-read_input_bits",
      "description": "读取离散输入位",
      "description_en": "read discrete input bits"
    },
    {
      "action_name": "auto-read_holding_registers",
      "description": "读取保持寄存器",
      "description_en": "read holding registers"
    },
    {
      "action_name": "auto-read_input_registers",
      "description": "读取输入寄存器",
      "description_en": "read input registers"
    },
    {
      "action_name": "auto-write_single_coil_bit",
      "description": "写入单个线圈位",
      "description_en": "write a single coil bit"
    },
    {
      "action_name": "auto-write_single_holding_register",
      "description": "写入单个保持寄存器",
      "description_en": "write a single holding register"
    },
    {
      "action_name": "auto-write_multiple_coil_bits",
      "description": "写入多个线圈位",
      "description_en": "write multiple coil bits"
    },
    {
      "action_name": "auto-write_multiple_holding_registers",
      "description": "写入多个保持寄存器",
      "description_en": "write multiple holding registers"
    },
    {
      "action_name": "auto-mask_write_holding_register",
      "description": "按掩码写入保持寄存器",
      "description_en": "mask-write a holding register"
    },
    {
      "action_name": "auto-write_and_read_holding_registers",
      "description": "写入并读取保持寄存器",
      "description_en": "write and read holding registers"
    },
    {
      "action_name": "auto-get_protocol_identifier",
      "description": "获取协议标识符",
      "description_en": "get protocol identifier"
    }
  ]
}

